"""widget.py — the figure as a native anywidget (template; no iframe). The front-end (dist/widget.js, dist/widget.css) is generated by build.mjs.

    from widget import CoreadFigure
    w = CoreadFigure(state=0)                # JupyterLab: put `w` at the end of a cell.   marimo: mo.ui.anywidget(w)
    w.state = 2                              # kernel -> figure: walk to state 2
    w.t = 8; w.lang = "en"; w.theme = "light"
    w.state, w.t, w.done                     # figure -> kernel: what the reader pressed / slid, and whether the figure has stopped moving
    w.reading                                # figure -> kernel: what is on the screen, as text and numbers
Both directions are tested (make_check.py's marimo steps): a trait the figure writes must come back as a number in Python, and a number written in Python must move the figure.
"""
import json
import pathlib

import anywidget
import traitlets

HERE = pathlib.Path(__file__).resolve().parent
CONFIG = json.loads((HERE / "config.json").read_text(encoding="utf-8"))
STATES = CONFIG["chapters"][-1][2] + 1        # the number of states is never typed: it is the last state of the last chapter in config.json


class CoreadFigure(anywidget.AnyWidget):
    _esm = HERE / "dist" / "widget.js"
    _css = HERE / "dist" / "widget.css"

    # both ways: the reader's hands and Python's writes
    state = traitlets.Int(0).tag(sync=True)
    lang = traitlets.Enum(["ja", "en"], default_value="ja").tag(sync=True)
    t = traitlets.Int(-1).tag(sync=True)                       # -1 = follow the state; else a position of the figure's text
    theme = traitlets.Enum(["dark", "light", "auto"], default_value="dark").tag(sync=True)
    # figure -> kernel (owned by the figure)
    done = traitlets.Bool(True).tag(sync=True)                 # the figure has stopped moving (a capture or a check waits for it)
    reading = traitlets.Dict({}).tag(sync=True)                # {state, chapter, lang, t, kicker, readout, chips}

    @traitlets.validate("state")
    def _clamp_state(self, proposal):
        return max(0, min(STATES - 1, int(proposal["value"])))
